"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["30961"],{96885(e){e.exports=JSON.parse('{"id":"FIN-998","slug":"base-year","term":"Base Year","also_known_as":[],"difficulty":"Intermediate","definition":"A base year is the year chosen as the reference point for an index or for adjusting data, typically assigned a value of 100 so that values in other years can be compared with it.","explanation":["Base years are used in index numbers and in calculations that adjust for inflation. They provide a fixed starting point against which changes can be measured.","For example, if a price index has a base year of 2020 set at 100 and the index reads 118 in 2025, prices rose by 18% between 2020 and 2025.","Base years are also used to calculate real GDP. Output in each year is valued at the prices of the base year, so that changes in real GDP reflect changes in quantities rather than prices.","The choice of base year can affect how data is interpreted. Statistical agencies update base years periodically, often every five or ten years, to reflect changes in the economy, such as new products and shifting spending patterns. When a base year changes, the whole series is usually recalculated, so that comparisons remain consistent.","A base year should ideally be a fairly normal year, without major disruptions such as recessions or crises, so that comparisons are not distorted. Some modern indices use chain-linking, updating the weights regularly rather than relying on a single fixed base year."],"note":"","total":1500,"prev":{"slug":"base-case","term":"Base Case"},"next":{"slug":"basel-accords","term":"Basel Accords"}}')}}]);